<script>
(function () {
  var filterButtons = document.querySelectorAll('[data-filter]');
  var cards = document.querySelectorAll('.card');
  var status = document.getElementById('status');

  function applyFilter(value) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = value === 'all' || card.dataset.light === value;
      card.hidden = !match;
      if (match) shown++;
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.dataset.filter === value));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' plants.';
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () { applyFilter(btn.dataset.filter); });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    var label = btn.querySelector('.label');
    btn.addEventListener('click', function () {
      var planted = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(planted));
      label.textContent = planted ? 'Planted' : 'Mark as planted';
      card.classList.toggle('is-planted', planted);
    });
  });

  applyFilter('all');
})();
</script>
